with tarfile.open(p,'r:gz') as t:
 members=t.getmembers();assert len(members)==len(expected)and{m.name for m in members}==set(expected)
 for m in members:
  q=pathlib.PurePosixPath(m.name);assert m.isfile()and not q.is_absolute()and '..'not in q.parts
  b=t.extractfile(m).read();assert hashlib.sha256(b).hexdigest()==expected[m.name]
  dst=root.joinpath(*q.parts);assert root in dst.resolve().parents
  if dst.exists():assert not dst.is_symlink()and hashlib.sha256(dst.read_bytes()).hexdigest()==expected[m.name]
  else:
   with dst.open('xb')as f:f.write(b)
   dst.chmod(m.mode&0o777)
assert {x.name for x in (root/'tools').iterdir()if x.is_file()}=={pathlib.PurePosixPath(k).name for k in expected if k.startswith('tools/')}
